/** 拾取飘字稀有度色（Item.GetPopupRarityColor Item.cs:633-696 1:1） */
const POPUP_RARITY_COLORS: Record<number, string> = {
  1: '#9696FF', 2: '#96FF96', 3: '#FFC896', 4: '#FF9696', 5: '#FF96FF',
  [-11]: '#FFAF00', [-1]: '#828282', 6: '#D2A0FF', 7: '#96FF0A', 8: '#FFFF0A',
  9: '#05C8FF', 10: '#FF2864',
};
const POPUP_RARITY_COLOR_11PLUS = '#B428FF';   // ≥11（Item.cs:692-694）
/** 稀有度 → 飘字色（表查 + ★刀3-1 mod 档色查表 + ≥11 档） */
function popupRarityColor(rare: number): string {
  return POPUP_RARITY_COLORS[rare] ?? modRarityColorOf(rare) ?? (rare >= 11 ? POPUP_RARITY_COLOR_11PLUS : '#FFFFFF');
}

/** 词缀显示名（Item.AffixName Item.cs:1195-1203：prefix≤0 → 本名；否则
 *  Lang.GetPrefixedItemName Lang.cs:225-239——CombineFormat.Prefix l10n 格式串拼装。
 *  ★BJ390（2026-09-28）用户实报 <> 面：旧实相裸拼接（词缀名+本名）缺 per-language
 *  格式——zh-Hans 官方格式 "‹{PrefixName}›{ItemName}"（U+2039/203A 单尖引号无空格,
 *  用户观察的 "<>" 即此对引号）、en-US "{PrefixName} {ItemName}"（空格）、zh-Hant
 *  无分隔。本仓 l10n 产物已带该键（tools/l10n/*.Items.json 全语种 → public/l10n） */
function popupAffixName(prefix: number | undefined, baseName: string): string {
  if (!prefix) return baseName;
  const key = PREFIX_NAMES[String(prefix)];
  if (!key) return baseName;
  const t = Lang.text(`Prefix.${key}`);
  const prefixName = t && t !== `Prefix.${key}` ? t : key;
  return formatPrefixedName(prefixName, baseName, Lang.has('CombineFormat.Prefix') ? Lang.text('CombineFormat.Prefix') : null);
}

/** 钱币飘字档位（PopupText.cs:233-247/:352-366）：面值 → [色, 最短寿命] */
function popupCoinTier(value: number): [string, number] {
  if (value >= 1000000) return ['#DCDCC6', 300];   // 铂 (220,220,198)
  if (value >= 10000) return ['#E0C95C', 240];     // 金 (224,201,92)
  if (value >= 100) return ['#B5C0C1', 180];       // 银 (181,192,193)
  return ['#F68A60', 120];                         // 铜 (246,138,96)
}

/** 钱币面值文本（PopupText.ValueToName :543-583 1:1：贪心除档，空档跳过，
 *  空格连接——"1 金币 50 银币"） */
function popupCoinText(value: number): string {
  const parts: string[] = [];
  let v = Math.max(0, value);
  for (let i = COIN_KEYS.length - 1; i >= 0; i--) {
    const n = Math.floor(v / COIN_VALUES[i]);
    if (n > 0) {
      parts.push(`${n} ${Lang.itemNameByKey(String(COIN_KEYS[i]))}`);
      v -= n * COIN_VALUES[i];
    }
  }
  return parts.join(' ') || `0 ${Lang.itemNameByKey(String(COIN_KEYS[0]))}`;
}
