/** ReplaceTile_IsValidSolid（WorldGen.cs:63247-63256）：tileSolid && !tileSolidTop
 *  && (tileRope ? true : !tileFrameImportant)。本仓 TileDef.solid=参与碰撞域
 *  （≈tileSolid&&!solidTop）、.platform 排平台、.rope=Main.tileRope 代理；
 *  frameImportant 用 VAN_TILE_FRAME_IMPORTANT 真表——TileDef.framed 是"多格框架"
 *  建模旗（平台 19 等单格 style 帧族未置）,不同域勿替代（VanillaTileFlags.ts 头注定谳） */
function replaceTileIsValidSolid(sheet: number): boolean {
  const d = TILE_DEFS[TILE_INTERNAL_BY_SHEET.get(sheet) ?? -1];
  if (!d) return false;
  if (!(d.solid && !d.platform)) return false;
  return d.rope ? true : !VAN_TILE_FRAME_IMPORTANT.has(sheet);
}
/** ★SW-BN5 2026-09-08：WouldTileReplacementWork 绳邻特例（WorldGen.cs:63220-63236 1:1，
 *  BJ18 §6 D6 分期清偿）——目标为绳（Main.tileRope[tile.type],tileRope 全表
 *  Main.cs:9452-9460=TILE_ROPE_SHEETS）且 InWorld(x,y,2)（:9642-9649,x/y∈[2,size-2)）
 *  时：放置物 314 矿车轨且左右邻 active 314 / 放置物∈Platforms 且左右邻 active 平台 /
 *  放置物 380 种植盆且左右邻 active 380 → true。仅当外门绳支（Player.cs:40328-40334,
 *  调用位 ropeTargetArm）先放行才可达；绳目标两侧皆非 validSolid（:63247-63258 绳
 *  tileSolid=false）→ 族支恒不匹配,本支是绳目标域的唯一放行路（wiki 规则：绳可换
 *  平台/种植盆/矿车轨,须紧邻左/右有同型）。 */
function wouldTileReplacementWorkRopeArm(
  st: import('../world/TileStore').TileStore, x: number, y: number, placedSheet: number,
): boolean {
  const tsheet = TILE_DEFS[st.type[st.idx(x, y)]]?.vanilla?.sheet ?? -1;
  if (!TILE_ROPE_SHEETS.has(tsheet)) return false;                       // Main.tileRope[tile.type]
  if (x < 2 || y < 2 || x >= st.w - 2 || y >= st.h - 2) return false;    // InWorld(x,y,2)
  for (const dx of [-1, 1] as const) {
    const nx = x + dx, ny = y;
    if (!st.inBounds(nx, ny) || !st.hasTile(nx, ny)) continue;           // tile2/3 != null && active()
    const nSheet = TILE_DEFS[st.type[st.idx(nx, ny)]]?.vanilla?.sheet ?? -1;
    if (placedSheet === 314 ? nSheet === 314                             // :63223-63226
      : placedSheet === 380 ? nSheet === 380                             // :63232-63235
        : PLATFORMS_SHEETS.has(placedSheet) && PLATFORMS_SHEETS.has(nSheet)) return true;   // :63227-63230
  }
  return false;
}
/** ★SW-BJ12 2026-09-07：Block Swap 旧块掉落门比对面（vanilla Player.cs:40347-40354
 *  `!IgnoresTileReplacementDropCheckWhenBeingPlaced[placed] && KillTile_GetItemDrops
 *  (target).dropItem == HeldItem.type → 不可换`）。原 wiki C5 草/苔/灰烬草族的
 *  机制锚：草族 2/23/109/199/477/492 掉泥土（:64528-64534 dropItem=2）、丛林/蘑菇草
 *  60/70 掉泥（176）、苔族掉石（3）、苔砖族掉灰砖（129）、灰烬草掉灰烬块（172）——
 *  「目标掉落==手持物品」即拒（防土换土无限+草换土）。
 *  ★旧比对 `tdef.drop === itemDef.key`（number===string）恒 false = 死门。
 *  本仓等价判据：drop item id == 放置物品 vid（真物品）；place_v_* 面板物品无
 *  vid → 掉落物品 createTile == 放置 tile sheet（面板物品承载同一 tile 语义）。
 *  Ignores{158,30}（TileID.cs:217）= 放置 tile sheet 域豁免。 */
export function blockSwapDropMatches(
  targetDef: { drop?: string | number | null } | undefined,
  placeVid: number, placeSheet: number,
): boolean {
  if (IGNORES_REPLACEMENT_DROP_CHECK_SHEETS.has(placeSheet)) return false;
  const drop = targetDef?.drop;
  if (drop == null) return false;
  if (typeof drop === 'number') {
    if (placeVid >= 0 && drop === placeVid) return true;
    return placeSheet >= 0 && vanillaItemCreateTile(drop) === placeSheet;
  }
  return false;   // string drop 键域不走本门（本仓 TILE_DEFS 无 string drop 实例）
}
export interface FamilySwapCtx {
  targetSheet: number; placedSheet: number; style: number;
  targetFrameX: number; targetFrameY: number; targetLiquid: number;
  placedItemId: number;              // SortingPriorityRopes 判据（HeldItem.type 域）
  targetDropIsPlacedItem: boolean;   // KillTile_GetItemDrops(dropItem)==HeldItem.type
  playerOverlapsTargetTile: boolean; // CheckPlatformSolidityForBlockSwap 的 Hitbox.Intersects
  getGoodWorld: boolean;
}
/** 族目标 verdict（行号对照：Player.cs 1457）。只对 BLOCK_SWAP_FAMILY_TARGET_SHEETS
 *  内目标调用；true/false 即定谳（false 须压掉通用门——族段命中即整函数早退） */
export function validTileForReplacementFamilies(ctx: FamilySwapCtx): boolean {
  const ts = ctx.targetSheet, ps = ctx.placedSheet, style = ctx.style;
  // :40245-40247 SortingPriorityRopes[HeldItem.type] != -1 → false
  if (ROPE_ITEM_VIDS.has(ctx.placedItemId)) return false;
  // :40249-40251 Main.tileMoss[type]（放置物为苔）→ false
  if (MOSS_CONVERT_SHEETS.has(ps)) return false;
  // :40253-40255 DoesntPlaceWithTileReplacement[type] → false
  if (BLOCK_SWAP_DOESNT_PLACE_SHEETS.has(ps)) return false;
  // :40257-40259 DoesntGetReplacedWithTileReplacement[tile.type] → false
  if (BLOCK_SWAP_DOESNT_GET_REPLACED_SHEETS.has(ts)) return false;
  // :40261-40264 CheckSpecificValidtyCaseForBlockSwap（:40376-40396）：仅当目标
  // Falling 或目标∈{546 Grate,557 GrateClosed} 才可能拒——族目标二者皆非 → 恒通过
  // :40265-40268 CheckPlatformSolidityForBlockSwap（:40363-40374）：平台/380 目标
  // +非平台非 380 放置物+玩家盒相交 → false
  if ((PLATFORMS_SHEETS.has(ts) || ts === 380) && !PLATFORMS_SHEETS.has(ps) && ps !== 380
    && ctx.playerOverlapsTargetTile) return false;
  // :40269-40271 Main.tileCut[tile.type] → false（族 tile 均不在 tileCut 表,恒过）
  if (TILE_CUT_SHEETS.has(ts)) return false;
  // :40273-40275 Platforms[tile.type] && tile.type==type → frameY != style*18
  if (PLATFORMS_SHEETS.has(ts) && ts === ps) return ctx.targetFrameY !== style * 18;
  // :40277-40294 Torches[tile.type]
  if (ts === 4) {
    if (ctx.targetLiquid > 0) {
      // :40281 放置物为炬（type==4）且 style∉{8,11,17}（水炬三式）→ false
      if (ps === 4 && style !== 8 && style !== 11 && style !== 17) return false;
      // :40285-40287 GetTileData(type,style).WaterPlacement != Allowed → false
      // （liquidSpecOf=TileObjectData 液体两维提取,子样式档回落基档=GetTileData 语义）
      const spec = liquidSpecOf(ps);
      if (spec && (spec.liqStyles?.[String(style)] ?? spec.liq).water !== 'allowed') return false;
    }
    // :40291-40293 tile.type==type → frameY != style*22
    if (ts === ps) return ctx.targetFrameY !== style * 22;
  }
  // :40296-40309 Campfires[tile.type]（无炬式豁免,液面门只查 WaterPlacement）
  if (ts === 215) {
    if (ctx.targetLiquid > 0) {
      const spec = liquidSpecOf(ps);
      if (spec && (spec.liqStyles?.[String(style)] ?? spec.liq).water !== 'allowed') return false;
    }
    if (ts === ps) return Math.floor(ctx.targetFrameX / 54) !== style;
  }
  // :40311-40317 BasicChest[tile.type] && BasicChest[type]：同 style → tile.type!=type
  // （异型同 style 可换,如 21↔467）,异 style → true（同型异 style 换的判定主体）
  if (BASIC_CHEST_SHEETS.has(ts) && BASIC_CHEST_SHEETS.has(ps)) {
    return Math.floor(ctx.targetFrameX / 36) === style ? ts !== ps : true;
  }
  // :40319-40325 BasicDresser 同式（frameX/54）
  if (ts === 88 && ps === 88) {
    return Math.floor(ctx.targetFrameX / 54) === style ? ts !== ps : true;
  }
  // ---- :40328-40360 通用尾段（族段各支 tile.type==type 皆未命中的回落面）----
  // :40328-40334 tileRope[tile.type]：族 tile 全非绳 → flag 恒 false,不建模
  // :40336-40338 !flag && tileFrameImportant[type] && !Platforms[type] → false
  if (VAN_TILE_FRAME_IMPORTANT.has(ps) && !PLATFORMS_SHEETS.has(ps)) return false;
  // :40340-40342 tile.type==type → false
  if (ts === ps) return false;
  // :40344-40346 tile.type==230（CrispyHoneyBlock）&& Main.getGoodWorld → false
  if (ts === 230 && ctx.getGoodWorld) return false;
  // :40348-40354 !IgnoresTileReplacementDropCheckWhenBeingPlaced[type]（{158,30}）
  //   && dropItem==HeldItem.type → false
  if (!IGNORES_REPLACEMENT_DROP_CHECK_SHEETS.has(ps) && ctx.targetDropIsPlacedItem) return false;
  // :40356-40358 WouldTileReplacementWork（WorldGen.cs:63209-63246）：放置物/目标至少
  //   同属一有效族（双实心/双炬/双篝火/双平台/双箱/双柜）或 flag4（两侧皆"实心或平台"）
  //   才放行。绳邻特例（:63220-63236）需目标为绳——族目标恒不触发（★SW-BN5：绳目标
  //   域的该支已接通用路径 wouldTileReplacementWorkRopeArm,见 swapOk 绳支注）；
  //   Chest.IsLocked（:63242 flag5 末项）仅双箱时可及——双箱已在 :40311 早退,族目标
  //   域内不可达（注释级豁免,非近似）。
  if (CONVERSION_GRASS_SHEETS.has(ps) || ps === 633) return false;   // :63216-63218
  const fSolid = !replaceTileIsValidSolid(ps) || !replaceTileIsValidSolid(ts);
  const fTorch = !(ps === 4) || !(ts === 4);                // IsValidTorch=Torches 表（:63260）
  const fCamp = !(ps === 215) || !(ts === 215);             // IsValidCampfire（:63265）
  const fPlat = !PLATFORMS_SHEETS.has(ps) || !PLATFORMS_SHEETS.has(ts);
  const f4 = (!replaceTileIsValidSolid(ps) && !PLATFORMS_SHEETS.has(ps))
    || (!replaceTileIsValidSolid(ts) && !PLATFORMS_SHEETS.has(ts));
  const fChest = !BASIC_CHEST_SHEETS.has(ps) || !BASIC_CHEST_SHEETS.has(ts);
  const fDresser = !(ps === 88) || !(ts === 88);            // IsValidDresser（:63275）
  return !(fPlat && fTorch && fCamp && fSolid && f4 && fChest && fDresser);
}
/** Chest.CanDestroyChest（Chest.cs:590-606）：锚格记录含非空物品（id>0 且 stack>0）
 *  → false（不可毁）。world.chests 登记锚=物件左上格（放置链 :13404 注），梳妆台 88
 *  共用同表。破坏门（breakTile→shouldTileSurviveAt）与钻头链（killTileCtx）同源 */
export function chestDestroyableAt(chests: readonly ChestData[], cx: number, cy: number): boolean {
  const c = chests.find((cc) => cc.x === cx && cc.y === cy);
  if (!c) return true;   // 无登记 = 可毁（Chest.cs:594-597）
  return !c.items.some((it) => it != null && it.id > 0 && it.stack > 0);
}

// ---- SW-K1 2026-09-03：CanKillTile 消费面三件（Wiring 全式 / 割草机 4049 / Dirt Rod 114）----
// 纯函数层（TileStore 演算可测；Game 私有方法只做尘/音/实体接线）

/** WorldGen.CanKillTile(i, j, SpecialKillTileContext.MowingTheGrass)（WorldGen.cs
 *  :3974-3977 枚举 + :62693-62704 包装）：context==MowingTheGrass 且格型 ∈
 *  {2 草, 109 神圣草} → 恒 true（【先于】全函数体的早返——草上压箱也照割），
 *  其余落全函数 canKillTileAt。★活格门：context 包装只查 tile==null 与 type，
 *  不查 active——幽灵格（flags=0 残型）原版会"空转换+喷尘"，本仓按幽灵保域口径
 *  以 isActive 短路（不可割不喷尘），差量=幽灵格 3 粒尘，无可见行为。
 *  ★G1 谓词形态批（2026-09-04）备案：isActive（nactive）门同时使【已致动草】同短路
 *  （致动草 type 仍 2/109 但 nactive=false）——原版包装无 active 门,致动草会走
 *  KillTile 空转换;本仓已备案按幽灵保域同口径处理（差量=致动草割尘,行为面无可见
 *  差异——inActive 草不可见）,行为不动仅补注 */
export function canKillTileMowingAt(
  st: import('../world/TileStore').TileStore, x: number, y: number, ctx?: KillTileCtx,
): boolean {
  if (st.inBounds(x, y) && st.isActive(x, y)) {
    const sheet = TILE_DEFS[st.type[st.idx(x, y)]]?.vanilla?.sheet;
    if (sheet === 2 || sheet === 109) return true;
  }
  return canKillTileAt(st, x, y, ctx);
}

/** Player.MowGrassTile 的转换目标（Player.cs:20522-20532 switch(tile.type)）：
 *  2 草 → 477 修剪草（GolfGrass）/ 109 神圣草 → 492 神圣修剪草（GolfGrassHallowed）；
 *  其余 0 = 不动。★1.4.4+ 起割草目标是高尔夫草两型（TileID.cs:1391/:1421） */
export function mowedSheetOf(sheet: number): number {
  return sheet === 2 ? 477 : sheet === 109 ? 492 : 0;
}

