          // 同款拒绝。tile 88（大橱柜）排除门（:40950）本仓无该容器等价物，登记
          this.useSwing(heldDef);
          const st = this.world.store;
          const ltx = tx, lty = ty;
          // ★SW-BJ52 2026-09-10：定位收原版精确域——PlaceThing_LockChest 门=
