            maxShots: slowMagicSprayPlan(this.player.slowMagicUse, animDur27, cw.useTime,
              itemCombat(critVid)?.useAnimation, this.swing.dur,
              reuseDelayBakedOf(critVid, this.heldPrefixStat()?.spd ?? 1))?.shots
