      const sp0 = anchorSpecOf(def.vanilla.sheet);
      if (!sp0) return null;
      const spSub = anchorSpecOf(def.vanilla.sheet, itemDef.placeStyle ?? 0);
      const sp = (spSub && spSub !== sp0
        && ((def.w ?? 1) !== spSub.w || (def.h ?? 1) !== spSub.h)) ? sp0 : spSub;
      if (!sp) return null;
