        if (!inOpposingTeam(this.player, rp)) continue;         // 1457 :4490-4501（含双方 hostile 门；1456 :4290-4301）
        if (!hitRect(rp.x, rp.y, rp.w, rp.h)) continue;
        // ★1457 视线门（ItemCheck_MeleeHitPVP 命中循环门禁串 :44429
